<script setup lang="ts">
  import { computed, reactive } from 'vue';
  import AsciiEffect from '@registry/new-york/ascii-effect/AsciiEffect.vue';
  import {
    FLOW_COLORS,
    GLITCH_COLORS,
    IMAGE_COLORS,
  } from '@registry/new-york/ascii-effect/ascii-effect.ts';
  import type {
    AsciiEffectColorMode,
    AsciiEffectDither,
    AsciiEffectFit,
    AsciiEffectVariant,
  } from '@registry/new-york/ascii-effect/types';
  import type { Pane } from 'tweakpane';

  // Chrome bust from the upstream demo, inlined at 800px (plenty for ~200 ASCII columns).
  const imageSrc =
    'data:image/webp;base64,';

  const PALETTES: Record<string, readonly string[]> = {
    mono: IMAGE_COLORS,
    flow: FLOW_COLORS,
    glitch: GLITCH_COLORS,
  };

  const variant: AsciiEffectVariant = 'flow';
  const colorMode: AsciiEffectColorMode = 'gradient';
  const dither: AsciiEffectDither = 'floyd-steinberg';
  // The docs panel is taller than the 16:9 bust, so contain keeps the face in frame.
  const fit: AsciiEffectFit = 'contain';

  const params = reactive({
    variant,
    palette: 'mono',
    colorMode,
    dither,
    fit,
    chars: ' .:-=+*#%@',
    fontSize: 6,
    scale: 1,
    brightnessBoost: 2.2,
    contrast: 1.1,
    invert: false,
    flowSpeed: 0.22,
    flowStrength: 12,
    flowDirection: 0,
    mouseRadius: 150,
    mouseStrength: 22,
    glitchIntensity: 0.8,
    glitchFrequency: 1.8,
  });

  const colors = computed(() => PALETTES[params.palette] ?? IMAGE_COLORS);

  function onPaneCreated(pane: Pane) {
    pane.addBinding(params, 'variant', {
      options: { Image: 'image', Flow: 'flow', Glitch: 'glitch' },
    });
    pane.addBinding(params, 'palette', {
      options: { Mono: 'mono', Cyan: 'flow', Lime: 'glitch' },
    });
    pane.addBinding(params, 'colorMode', {
      options: { Gradient: 'gradient', Source: 'source' },
    });
    pane.addBinding(params, 'dither', {
      options: {
        'Floyd–Steinberg': 'floyd-steinberg',
        Bayer: 'bayer',
        None: 'none',
      },
    });
    pane.addBinding(params, 'fit', {
      options: { Contain: 'contain', Cover: 'cover', Stretch: 'stretch' },
    });
    pane.addBinding(params, 'chars');
    pane.addBinding(params, 'fontSize', { min: 4, max: 16, step: 0.5 });
    pane.addBinding(params, 'scale', { min: 0.5, max: 2, step: 0.05 });
    pane.addBinding(params, 'brightnessBoost', { min: 0.5, max: 4, step: 0.1 });
    pane.addBinding(params, 'contrast', { min: 0.5, max: 2, step: 0.05 });
    pane.addBinding(params, 'invert');
    pane.addBinding(params, 'flowSpeed', { min: 0, max: 1, step: 0.01 });
    pane.addBinding(params, 'flowStrength', { min: 0, max: 40, step: 1 });
    pane.addBinding(params, 'flowDirection', { min: 0, max: 360, step: 5 });
    pane.addBinding(params, 'mouseRadius', { min: 0, max: 300, step: 5 });
    pane.addBinding(params, 'mouseStrength', { min: 0, max: 60, step: 1 });
    pane.addBinding(params, 'glitchIntensity', { min: 0, max: 1, step: 0.05 });
    pane.addBinding(params, 'glitchFrequency', { min: 0, max: 5, step: 0.1 });
  }
</script>

<template>
  <ComponentDemo
    refreshable
    :code="`<script setup lang=&quot;ts&quot;>
  import AsciiEffect from '~/components/ui/ascii-effect/AsciiEffect.vue';
</script>

<template>
  <div class=&quot;relative h-130 overflow-hidden rounded-2xl&quot;>
    <AsciiEffect
      variant=&quot;flow&quot;
      image-src=&quot;/images/portrait.webp&quot;
      :font-size=&quot;6&quot;
      :scale=&quot;1&quot;
      fit=&quot;contain&quot;
      :flow-speed=&quot;0.22&quot;
      :flow-strength=&quot;12&quot;
      :mouse-radius=&quot;150&quot;
      :mouse-strength=&quot;22&quot;
    />
  </div>
</template>`"
  >
    <div class="relative size-full min-h-80 overflow-hidden bg-black">
      <AsciiEffect
        class="absolute inset-0 size-full"
        alt="Marble bust rendered as ASCII characters"
        :image-src="imageSrc"
        :variant="params.variant"
        :colors="colors"
        :color-mode="params.colorMode"
        :dither="params.dither"
        :fit="params.fit"
        :chars="params.chars"
        :font-size="params.fontSize"
        :scale="params.scale"
        :brightness-boost="params.brightnessBoost"
        :contrast="params.contrast"
        :invert="params.invert"
        :flow-speed="params.flowSpeed"
        :flow-strength="params.flowStrength"
        :flow-direction="params.flowDirection"
        :mouse-radius="params.mouseRadius"
        :mouse-strength="params.mouseStrength"
        :glitch-intensity="params.glitchIntensity"
        :glitch-frequency="params.glitchFrequency"
      />
      <div
        class="pointer-events-none absolute inset-x-0 bottom-0 flex items-center justify-between bg-linear-to-t from-black/80 to-transparent p-4 pt-16 font-mono text-[10px] tracking-[0.2em] text-white/45 uppercase"
      >
        <span>{{ params.variant }}</span>
        <span>Render / Live</span>
      </div>
      <ShaderPane
        expanded
        title="ASCII Effect"
        @on-pane-created="onPaneCreated"
      />
    </div>
  </ComponentDemo>
</template>
